52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
110	        if (hasReachedDailyRegistrationLimit()) {
111	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
112	        }
113	        if (hasReachedCityOwnerLimit(owner.getCity())) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
117	            return new ResponseEntity<>(HttpStatus.CONFLICT);
118	        }
119	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
120	        owner.setSharesHousehold(sharesHousehold(owner.getAddress(), owner.getCity()));
121	        owner.setLocality(resolveLocality(owner.getCity()));
122	        owner.setCity(resolveCity(owner.getCity()));
123	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
124	        owner.setMembershipNumber(membershipNumber);
125	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
126	        owner.setMembershipTier(membershipNumber <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        currentOwner.setAddress(ownerFieldsDto.getAddress());
142	        currentOwner.setCity(ownerFieldsDto.getCity());
143	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
144	        currentOwner.setLastName(ownerFieldsDto.getLastName());
145	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
146	        this.clinicService.saveOwner(currentOwner);
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Transactional
152	    @Override
153	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        this.clinicService.deleteOwner(owner);
159	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        HttpHeaders headers = new HttpHeaders();
170	        Pet pet = petMapper.toPet(petFieldsDto);
171	        owner.setId(ownerId);
172	        pet.setOwner(owner);
173	        pet.getType().setName(null);
174	        this.clinicService.savePet(pet);
175	        PetDto petDto = petMapper.toPetDto(pet);
176	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
177	            .buildAndExpand(pet.getId()).toUri());
178	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner != null) {
186	            Pet currentPet = this.clinicService.findPetById(petId);
187	            if (currentPet != null) {
188	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
189	                currentPet.setName(petFieldsDto.getName());
190	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
191	                this.clinicService.savePet(currentPet);
192	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	            }
194	        }
195	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
201	        HttpHeaders headers = new HttpHeaders();
202	        Visit visit = visitMapper.toVisit(visitFieldsDto);
203	        Pet pet = new Pet();
204	        pet.setId(petId);
205	        visit.setPet(pet);
206	        this.clinicService.saveVisit(visit);
207	        VisitDto visitDto = visitMapper.toVisitDto(visit);
208	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
209	            .buildAndExpand(visit.getId()).toUri());
210	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
211	    }
212	
213	
214	    /**
215	     * The number of owners at the head of the registration sequence that receive the
216	     * {@code 'FOUNDING'} membership tier. The first {@value #MAX_FOUNDING_OWNERS} owners ever
217	     * created are {@code 'FOUNDING'}; all later owners are {@code 'STANDARD'}.
218	     */
219	    private static final int MAX_FOUNDING_OWNERS = 100;
220	
221	    /**
222	     * The maximum number of owners that may be registered on any single calendar day.
223	     */
224	    private static final long MAX_DAILY_REGISTRATIONS = 20;
225	
226	    /**
227	     * Determines whether the daily owner-registration limit has already been reached. Owners are
228	     * counted by their {@link Owner#getRegistrationDate() registration date}, so once
229	     * {@value #MAX_DAILY_REGISTRATIONS} owners have been registered with today's date, no further
230	     * owners may be created today.
231	     *
232	     * @return {@code true} if today's registration limit has been reached
233	     */
234	    private boolean hasReachedDailyRegistrationLimit() {
235	        LocalDate today = LocalDate.now();
236	        long registeredToday = this.clinicService.findAllOwners().stream()
237	            .filter(existing -> today.equals(existing.getRegistrationDate()))
238	            .count();
239	        return registeredToday >= MAX_DAILY_REGISTRATIONS;
240	    }
241	
242	    /**
243	     * The maximum number of owners that may be registered in any single city.
244	     */
245	    private static final long MAX_OWNERS_PER_CITY = 8;
246	
247	    /**
248	     * Determines whether the given city has already reached its owner limit. Owners are matched to
249	     * the city using {@link #normalize(String)}, so the count ignores letter case and any
250	     * surrounding or repeated whitespace. Once {@value #MAX_OWNERS_PER_CITY} owners live in a city,
251	     * no further owners may be created there.
252	     *
253	     * @param city the city of the new owner, may be {@code null}
254	     * @return {@code true} if the city already contains {@value #MAX_OWNERS_PER_CITY} owners
255	     */
256	    private boolean hasReachedCityOwnerLimit(String city) {
257	        String normalized = normalize(city);
258	        long ownersInCity = this.clinicService.findAllOwners().stream()
259	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalized))
260	            .count();
261	        return ownersInCity >= MAX_OWNERS_PER_CITY;
262	    }
263	
264	    /**
265	     * Builds the customer code for a newly created owner, formatted as
266	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
267	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
268	     *
269	     * @param city the city of the new owner
270	     * @return the assigned customer code
271	     */
272	    private String nextCustomerCode(String city) {
273	        long ownersInCity = this.clinicService.findAllOwners().stream()
274	            .filter(existing -> Objects.equals(
275	                normalize(existing.getCity()), normalize(city)))
276	            .count();
277	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
278	    }
279	
280	    /**
281	     * Resolves the city to store for a newly created owner. The city is title-cased (so
282	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
283	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
284	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
285	     * surrounding or repeated whitespace.
286	     *
287	     * @param city the city supplied for the new owner, may be {@code null}
288	     * @return the city to store, or {@code null} if the input was {@code null}
289	     */
290	    private String resolveCity(String city) {
291	        if (city == null) {
292	            return null;
293	        }
294	        String normalized = normalize(city);
295	        if (!normalized.isEmpty()) {
296	            for (Owner existing : this.clinicService.findAllOwners()) {
297	                if (normalized.equals(normalize(existing.getCity()))) {
298	                    return existing.getCity();
299	                }
300	            }
301	        }
302	        return toTitleCase(city);
303	    }
304	
305	    /**
306	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
307	     * and lower-casing the remaining letters, preserving the original whitespace. For example
308	     * {@code "new  YORK"} becomes {@code "New  York"}.
309	     *
310	     * @param value the raw value, never {@code null}
311	     * @return the title-cased value
312	     */
313	    private static String toTitleCase(String value) {
314	        StringBuilder result = new StringBuilder(value.length());
315	        boolean startOfWord = true;
316	        for (int i = 0; i < value.length(); i++) {
317	            char c = value.charAt(i);
318	            if (Character.isWhitespace(c)) {
319	                startOfWord = true;
320	                result.append(c);
321	            } else if (startOfWord) {
322	                result.append(Character.toTitleCase(c));
323	                startOfWord = false;
324	            } else {
325	                result.append(Character.toLowerCase(c));
326	            }
327	        }
328	        return result.toString();
329	    }
330	
331	    /**
332	     * Resolves the locality of a newly created owner relative to the owners present at the moment
333	     * it is created. The value is {@code "local"} when the new owner's city is the single most
334	     * common city among the existing owners, and {@code "remote"} otherwise. Cities are matched
335	     * using {@link #normalize(String)}, so the comparison ignores letter case and any surrounding
336	     * or repeated whitespace. When there are no existing owners, or when two or more cities tie for
337	     * the highest owner count, no city is the sole most common one and the result is
338	     * {@code "remote"}.
339	     *
340	     * @param city the city supplied for the new owner, may be {@code null}
341	     * @return {@code "local"} if the city is the single most common city, otherwise {@code "remote"}
342	     */
343	    private String resolveLocality(String city) {
344	        String normalized = normalize(city);
345	        Map<String, Long> ownersPerCity = this.clinicService.findAllOwners().stream()
346	            .map(existing -> normalize(existing.getCity()))
347	            .filter(normalizedCity -> !normalizedCity.isEmpty())
348	            .collect(Collectors.groupingBy(normalizedCity -> normalizedCity, Collectors.counting()));
349	        long highestCount = ownersPerCity.values().stream()
350	            .mapToLong(Long::longValue)
351	            .max()
352	            .orElse(0L);
353	        if (highestCount == 0L) {
354	            return "remote";
355	        }
356	        List<String> mostCommonCities = ownersPerCity.entrySet().stream()
357	            .filter(entry -> entry.getValue() == highestCount)
358	            .map(Map.Entry::getKey)
359	            .toList();
360	        boolean isSingleMostCommon = mostCommonCities.size() == 1
361	            && mostCommonCities.get(0).equals(normalized);
362	        return isSingleMostCommon ? "local" : "remote";
363	    }
364	
365	    /**
366	     * Counts how many existing owners share the given last name. Last names are matched using
367	     * {@link #normalize(String)}, so the count ignores letter case and any surrounding or repeated
368	     * whitespace. This is evaluated against the owners present at the moment the new owner is
369	     * created, before the new owner is persisted, so the new owner does not count itself.
370	     *
371	     * @param lastName the last name of the new owner, may be {@code null}
372	     * @return the number of existing owners sharing the same last name
373	     */
374	    private int countNamesakes(String lastName) {
375	        String normalized = normalize(lastName);
376	        return (int) this.clinicService.findAllOwners().stream()
377	            .filter(existing -> normalized.equals(normalize(existing.getLastName())))
378	            .count();
379	    }
380	
381	    /**
382	     * Determines whether the new owner shares a household with an existing owner, meaning another
383	     * owner already has the same address and city. Both the address and the city are matched using
384	     * {@link #normalize(String)}, so the comparison ignores letter case and any surrounding or
385	     * repeated whitespace. This is evaluated against the owners present at the moment the new owner
386	     * is created, before the new owner is persisted, so the new owner does not count itself.
387	     *
388	     * @param address the address of the new owner, may be {@code null}
389	     * @param city    the city of the new owner, may be {@code null}
390	     * @return {@code true} if an existing owner already has the same address and city
391	     */
392	    private boolean sharesHousehold(String address, String city) {
393	        String normalizedAddress = normalize(address);
394	        String normalizedCity = normalize(city);
395	        return this.clinicService.findAllOwners().stream()
396	            .anyMatch(existing -> normalizedAddress.equals(normalize(existing.getAddress()))
397	                && normalizedCity.equals(normalize(existing.getCity())));
398	    }
399	
400	    /**
401	     * Determines whether the given telephone number is already used by any other owner.
402	     *
403	     * @param owner the candidate owner
404	     * @return {@code true} if an owner with the same telephone number already exists in the data store
405	     */
406	    private boolean isDuplicateOwner(Owner owner) {
407	        return this.clinicService.findAllOwners().stream()
408	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
409	    }
410	
411	    /**
412	     * Determines whether the given email address is already used by any other owner. An owner
413	     * without an email address is never considered a duplicate on this criterion. Email addresses
414	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
415	     * surrounding or repeated whitespace.
416	     *
417	     * @param owner the candidate owner
418	     * @return {@code true} if the owner provides an email already used by an existing owner
419	     */
420	    private boolean isDuplicateEmail(Owner owner) {
421	        String email = normalize(owner.getEmail());
422	        if (email.isEmpty()) {
423	            return false;
424	        }
425	        return this.clinicService.findAllOwners().stream()
426	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
427	    }
428	
429	    /**
430	     * Normalizes a telephone number to digits only by stripping spaces, dashes and parentheses, so
431	     * that a value such as {@code "(613) 555-0100"} is stored and compared as {@code "6135550100"}.
432	     * This is applied before an owner is stored and before the telephone-uniqueness check, so two
433	     * differently formatted representations of the same number are treated as duplicates. A
434	     * {@code null} value is returned unchanged.
435	     *
436	     * @param telephone the raw telephone number, may be {@code null}
437	     * @return the digits-only telephone number, or {@code null} if the input was {@code null}
438	     */
439	    private static String normalizeTelephone(String telephone) {
440	        if (telephone == null) {
441	            return null;
442	        }
443	        return telephone.replaceAll("[\\s()-]", "");
444	    }
445	
446	    /**
447	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
448	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
449	     * collapsed to a single space and the result is lower-cased. This is what makes
450	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
451	     * duplicates. A {@code null} value normalizes to the empty string.
452	     *
453	     * @param value the raw value, may be {@code null}
454	     * @return the normalized value, never {@code null}
455	     */
456	    private static String normalize(String value) {
457	        if (value == null) {
458	            return "";
459	        }
460	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
461	    }
462	
463	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
464	    @Override
465	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
466	        Owner owner = this.clinicService.findOwnerById(ownerId);
467	        if (owner != null) {
468	            Pet pet = owner.getPet(petId);
